class AdaptiveConcurrencyLimiter:
    def __init__(self, initial_limit=10, min_limit=5, max_limit=50):
        # Strict type validation for numeric parameters, explicitly rejecting booleans
        for name, val in [("initial_limit", initial_limit), ("min_limit", min_limit), ("max_limit", max_limit)]:
            if isinstance(val, bool) or not isinstance(val, (int, float)):
                raise ValueError(f"{name} must be a numeric value, not boolean or other type")

        self._initial_limit = float(initial_limit)
        self._min_limit = float(min_limit)
        self._max_limit = float(max_limit)
        self._limit = float(initial_limit)
        self._min_rtt = None
        self._in_flight = 0
        self._lock = None  # Placeholder for thread safety if needed

    @property
    def limit(self):
        return self._limit

    @property
    def in_flight(self):
        return self._in_flight

    @in_flight.setter
    def in_flight(self, value):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("in_flight must be an integer, not boolean or other type")
        if value < 0:
            raise ValueError("in_flight cannot be negative")
        self._in_flight = value

    def acquire(self):
        # Atomic check and increment
        current_in_flight = self._in_flight
        current_limit = int(self._limit)
        if current_in_flight < current_limit:
            self._in_flight = current_in_flight + 1
            return True
        return False

    def release(self, measured_rtt):
        # Strict type validation for measured_rtt
        if isinstance(measured_rtt, bool) or not isinstance(measured_rtt, (int, float)):
            raise ValueError("measured_rtt must be a numeric value, not boolean or other type")
        if measured_rtt < 0:
            raise ValueError("measured_rtt cannot be negative")

        # Atomic state mutation with rollback capability
        old_in_flight = self._in_flight
        old_limit = self._limit
        old_min_rtt = self._min_rtt

        try:
            # Decrement in-flight count
            self._in_flight = max(0, old_in_flight - 1)

            # First release: establish baseline RTT
            if old_min_rtt is None:
                self._min_rtt = measured_rtt
                return

            # Vegas-style adaptive logic:
            # Calculate RTT deviation from baseline
            rtt_deviation = measured_rtt - old_min_rtt

            if rtt_deviation > 0:
                # Latency spike detected: throttle down (multiplicative decrease)
                # Reduce limit by a factor based on severity of spike
                severity_factor = min(1.0, rtt_deviation / max(1.0, old_min_rtt))
                self._limit = max(self._min_limit, self._limit * (1.0 - severity_factor))
            else:
                # Healthy RTT: additive increase
                self._limit = min(self._max_limit, self._limit + 1.0)

            # Update min_rtt to reflect current baseline (slowly adapting)
            # Use exponential moving average for stability
            self._min_rtt = 0.9 * old_min_rtt + 0.1 * measured_rtt

        except Exception as e:
            # Full rollback on any failure
            self._in_flight = old_in_flight
            self._limit = old_limit
            self._min_rtt = old_min_rtt
            raise e

